using System.Text.Json;using GameTranslator.Core;
namespace GameTranslator.Translation.Tests;
public class ComparisonLogExporterTests {
 [Fact]public void SnapshotIncludesRotatedRowsAndSkipsPartialWrites(){var folder=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{var path=Path.Combine(folder,"comparison.jsonl");var row=new ComparisonEntry(DateTimeOffset.UtcNow,"one","GTA6","QuickMT","Hello.","مرحبًا.",null,new(),true);File.WriteAllText(path+".previous",JsonSerializer.Serialize(row)+"\n");File.WriteAllText(path,JsonSerializer.Serialize(row with{English="Go!"})+"\n{partial");var result=ComparisonLogExporter.Export(path,Path.Combine(folder,"export.jsonl"));Assert.Equal(2,result.Rows);Assert.Equal(1,result.Skipped);Assert.Equal(2,File.ReadAllLines(Path.Combine(folder,"export.jsonl")).Length);}finally{Directory.Delete(folder,true);}}
 [Fact]public void CredentialsAndUnknownFieldsAreNotExported(){var folder=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{var path=Path.Combine(folder,"comparison.jsonl");var row=new ComparisonEntry(DateTimeOffset.UtcNow,"one","GTA6","QuickMT","AIza"+new string('x',30),"مرحبًا.",null,new(),true);File.WriteAllText(path,JsonSerializer.Serialize(row));var output=Path.Combine(folder,"export.jsonl");ComparisonLogExporter.Export(path,output);Assert.DoesNotContain("AIza",File.ReadAllText(output));Assert.Contains("REDACTED",File.ReadAllText(output));Assert.Throws<ArgumentException>(()=>ComparisonLogExporter.Export(path,path));}finally{Directory.Delete(folder,true);}}
}
